class MedicationRow extends DataClass implements Insertable<MedicationRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int sortOrder;
  final String name;
  final MedKind kind;

  /// Human dose text as the user writes it ("10 mg", "2 caps").
  final String? dose;
  final double? doseAmount;
  final String? doseUnit;

  /// Any number of daily times, `HH:mm`.
  final List<String> times;
  final TakenWith takenWith;
  final String? takenWithNote;
  final String? notes;
  final bool active;

  /// Units left (refill count) and the threshold that triggers a refill alert.
  final int? stock;
  final int? refillAt;
  final String? courseId;

  /// Titration schedule: `[{"from":"2026-10-01","dose":"5 mg","doseAmount":5}, …]`.
  final List<Object?> titration;
  final int? color;
  const MedicationRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.sortOrder,
    required this.name,
    required this.kind,
    this.dose,
    this.doseAmount,
    this.doseUnit,
    required this.times,
    required this.takenWith,
    this.takenWithNote,
    this.notes,
    required this.active,
    this.stock,
    this.refillAt,
    this.courseId,
    required this.titration,
    this.color,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['sort_order'] = Variable<int>(sortOrder);
    map['name'] = Variable<String>(name);
    {
      map['kind'] = Variable<String>(
        $MedicationsTable.$converterkind.toSql(kind),
      );
    }
    if (!nullToAbsent || dose != null) {
      map['dose'] = Variable<String>(dose);
    }
    if (!nullToAbsent || doseAmount != null) {
      map['dose_amount'] = Variable<double>(doseAmount);
    }
    if (!nullToAbsent || doseUnit != null) {
      map['dose_unit'] = Variable<String>(doseUnit);
    }
    {
      map['times'] = Variable<String>(
        $MedicationsTable.$convertertimes.toSql(times),
      );
    }
    {
      map['taken_with'] = Variable<String>(
        $MedicationsTable.$convertertakenWith.toSql(takenWith),
      );
    }
    if (!nullToAbsent || takenWithNote != null) {
      map['taken_with_note'] = Variable<String>(takenWithNote);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['active'] = Variable<bool>(active);
    if (!nullToAbsent || stock != null) {
      map['stock'] = Variable<int>(stock);
    }
    if (!nullToAbsent || refillAt != null) {
      map['refill_at'] = Variable<int>(refillAt);
    }
    if (!nullToAbsent || courseId != null) {
      map['course_id'] = Variable<String>(courseId);
    }
    {
      map['titration'] = Variable<String>(
        $MedicationsTable.$convertertitration.toSql(titration),
      );
    }
    if (!nullToAbsent || color != null) {
      map['color'] = Variable<int>(color);
    }
    return map;
  }

  MedicationsCompanion toCompanion(bool nullToAbsent) {
    return MedicationsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      sortOrder: Value(sortOrder),
      name: Value(name),
      kind: Value(kind),
      dose: dose == null && nullToAbsent ? const Value.absent() : Value(dose),
      doseAmount: doseAmount == null && nullToAbsent
          ? const Value.absent()
          : Value(doseAmount),
      doseUnit: doseUnit == null && nullToAbsent
          ? const Value.absent()
          : Value(doseUnit),
      times: Value(times),
      takenWith: Value(takenWith),
      takenWithNote: takenWithNote == null && nullToAbsent
          ? const Value.absent()
          : Value(takenWithNote),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      active: Value(active),
      stock: stock == null && nullToAbsent
