class TransactionRow extends DataClass implements Insertable<TransactionRow> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String walletId;
  final TxKind kind;

  /// Positive, with the direction coming from [kind] – except for
  /// [TxKind.adjustment], whose amount is signed (a negative adjustment
  /// lowers the wallet balance).
  final int amountMilli;
  final DateTime date;
  final String? budgetItemId;

  /// Transfers: destination wallet and the amount received there (may differ
  /// when currencies differ).
  final String? toWalletId;
  final int? toAmountMilli;
  final String? note;
  final List<String> tags;
  const TransactionRow({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.walletId,
    required this.kind,
    required this.amountMilli,
    required this.date,
    this.budgetItemId,
    this.toWalletId,
    this.toAmountMilli,
    this.note,
    required this.tags,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['wallet_id'] = Variable<String>(walletId);
    {
      map['kind'] = Variable<String>(
        $TransactionsTable.$converterkind.toSql(kind),
      );
    }
    map['amount_milli'] = Variable<int>(amountMilli);
    {
      map['date'] = Variable<DateTime>(
        $TransactionsTable.$converterdate.toSql(date),
      );
    }
    if (!nullToAbsent || budgetItemId != null) {
      map['budget_item_id'] = Variable<String>(budgetItemId);
    }
    if (!nullToAbsent || toWalletId != null) {
      map['to_wallet_id'] = Variable<String>(toWalletId);
    }
    if (!nullToAbsent || toAmountMilli != null) {
      map['to_amount_milli'] = Variable<int>(toAmountMilli);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    {
      map['tags'] = Variable<String>(
        $TransactionsTable.$convertertags.toSql(tags),
      );
    }
    return map;
  }

  TransactionsCompanion toCompanion(bool nullToAbsent) {
    return TransactionsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      walletId: Value(walletId),
      kind: Value(kind),
      amountMilli: Value(amountMilli),
      date: Value(date),
      budgetItemId: budgetItemId == null && nullToAbsent
          ? const Value.absent()
          : Value(budgetItemId),
      toWalletId: toWalletId == null && nullToAbsent
          ? const Value.absent()
          : Value(toWalletId),
      toAmountMilli: toAmountMilli == null && nullToAbsent
          ? const Value.absent()
          : Value(toAmountMilli),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      tags: Value(tags),
    );
  }

  factory TransactionRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return TransactionRow(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      walletId: serializer.fromJson<String>(json['walletId']),
      kind: $TransactionsTable.$converterkind.fromJson(
        serializer.fromJson<String>(json['kind']),
      ),
      amountMilli: serializer.fromJson<int>(json['amountMilli']),
      date: serializer.fromJson<DateTime>(json['date']),
      budgetItemId: serializer.fromJson<String?>(json['budgetItemId']),
      toWalletId: serializer.fromJson<String?>(json['toWalletId']),
      toAmountMilli: serializer.fromJson<int?>(json['toAmountMilli']),
      note: serializer.fromJson<String?>(json['note']),
      tags: serializer.fromJson<List<String>>(json['tags']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'walletId': serializer.toJson<String>(walletId),
      'kind': serializer.toJson<String>(
        $TransactionsTable.$converterkind.toJson(kind),
      ),
      'amountMilli': serializer.toJson<int>(amountMilli),
      'date': serializer.toJson<DateTime>(date),
      'budgetItemId': serializer.toJson<String?>(budgetItemId),
      'toWalletId': serializer.toJson<String?>(toWalletId),
      'toAmountMilli': serializer.toJson<int?>(toAmountMilli),
