    Value<int?> toAmountMilli = const Value.absent(),
    Value<String?> note = const Value.absent(),
    List<String>? tags,
  }) => TransactionRow(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    walletId: walletId ?? this.walletId,
    kind: kind ?? this.kind,
    amountMilli: amountMilli ?? this.amountMilli,
    date: date ?? this.date,
    budgetItemId: budgetItemId.present ? budgetItemId.value : this.budgetItemId,
    toWalletId: toWalletId.present ? toWalletId.value : this.toWalletId,
    toAmountMilli: toAmountMilli.present
        ? toAmountMilli.value
        : this.toAmountMilli,
    note: note.present ? note.value : this.note,
    tags: tags ?? this.tags,
  );
  TransactionRow copyWithCompanion(TransactionsCompanion data) {
    return TransactionRow(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      walletId: data.walletId.present ? data.walletId.value : this.walletId,
      kind: data.kind.present ? data.kind.value : this.kind,
      amountMilli: data.amountMilli.present
          ? data.amountMilli.value
          : this.amountMilli,
      date: data.date.present ? data.date.value : this.date,
      budgetItemId: data.budgetItemId.present
          ? data.budgetItemId.value
          : this.budgetItemId,
      toWalletId: data.toWalletId.present
          ? data.toWalletId.value
          : this.toWalletId,
      toAmountMilli: data.toAmountMilli.present
          ? data.toAmountMilli.value
          : this.toAmountMilli,
      note: data.note.present ? data.note.value : this.note,
      tags: data.tags.present ? data.tags.value : this.tags,
    );
  }

  @override
  String toString() {
    return (StringBuffer('TransactionRow(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('walletId: $walletId, ')
          ..write('kind: $kind, ')
          ..write('amountMilli: $amountMilli, ')
          ..write('date: $date, ')
          ..write('budgetItemId: $budgetItemId, ')
          ..write('toWalletId: $toWalletId, ')
          ..write('toAmountMilli: $toAmountMilli, ')
          ..write('note: $note, ')
          ..write('tags: $tags')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    createdAt,
    updatedAt,
    walletId,
    kind,
    amountMilli,
    date,
    budgetItemId,
    toWalletId,
    toAmountMilli,
    note,
    tags,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is TransactionRow &&
          other.id == this.id &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt &&
          other.walletId == this.walletId &&
          other.kind == this.kind &&
          other.amountMilli == this.amountMilli &&
          other.date == this.date &&
          other.budgetItemId == this.budgetItemId &&
          other.toWalletId == this.toWalletId &&
          other.toAmountMilli == this.toAmountMilli &&
          other.note == this.note &&
          other.tags == this.tags);
}

